const validLanguages=['en','fr','ar'];
function readStored(key,fallback){try{return JSON.parse(localStorage.getItem(key)??JSON.stringify(fallback))}catch{return fallback}}
function safeSet(key,value){try{localStorage.setItem(key,value);return true}catch{return false}}
function safeGet(key){try{return localStorage.getItem(key)}catch{return null}}
let lang=safeGet('smb-language')||safeGet('smb-lang')||'en'; if(!validLanguages.includes(lang))lang='en';
const tr=k=>t.en[k]||k;
function translateText(value,locale=lang){if(locale==='en')return value;const direct=t[locale][value];if(direct)return direct;if(value.startsWith('SMB ')&&t[locale][value.slice(4)])return `SMB ${t[locale][value.slice(4)]}`;return value}
let wish=readStored('smb-wishlist',[]), bag=readStored('smb-bag',[]);
if(!Array.isArray(wish))wish=[]; if(!Array.isArray(bag))bag=[]; wish=wish.filter(id=>products.some(p=>p.id===id)); bag=bag.filter(x=>x&&products.some(p=>p.id===x.id)&&Number.isFinite(Number(x.qty))&&Number(x.qty)>0).map(x=>({id:x.id,qty:Math.floor(Number(x.qty))})); safeSet('smb-language',lang);
const textSources=new WeakMap(), attrSources=new WeakMap();
function localize(root=document.body){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
  while(node=walker.nextNode()){
    if(!textSources.has(node))textSources.set(node,node.nodeValue);
    const original=textSources.get(node),trimmed=original.trim(),translated=translateText(trimmed);
    if(translated!==trimmed){const start=original.match(/^\s*/)?.[0]||'',end=original.match(/\s*$/)?.[0]||'';node.nodeValue=start+translated+end}
    else if(node.nodeValue!==original)node.nodeValue=original;
  }
  const attrs=['aria-label','title','placeholder','alt'];
  root.querySelectorAll?.('*').forEach(el=>attrs.forEach(attr=>{if(!el.hasAttribute(attr))return;let values=attrSources.get(el);if(!values){values={};attrSources.set(el,values)}if(!(attr in values))values[attr]=el.getAttribute(attr);const original=values[attr];el.setAttribute(attr,translateText(original))}));
}
const app=document.querySelector('#app'), modal=document.querySelector('#modal');
function img(file,cls='',alt='SMB'){return `<img class="${cls}" src="${A+file}" alt="${alt}" loading="lazy">`}
function card(p){return `<article class="product-card"><a class="product-image" href="#product/${p.id}">${img(p.images[0],'','SMB '+p.name)}<span class="card-collection">${p.collection}</span></a><button class="wish-btn ${wish.includes(p.id)?'active':''}" data-wish="${p.id}" aria-label="Add to wishlist">♡</button><button class="quick-btn" data-quick="${p.id}">${tr('quick')}</button><div class="product-meta"><a href="#product/${p.id}" class="product-name">${p.name}</a><span>${tr('request')}</span></div></article>`}
function headerText(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.querySelector('#language').value=lang}
function hero(){return `<section class="hero"><video class="hero-video" autoplay muted loop playsinline poster="${A+campaignImgs[0]}"><source src="${A+videos[0]}" type="video/mp4"></video><div class="hero-shade"></div><div class="hero-content"><p class="eyebrow">${tr('heroEyebrow')}</p><h1>SMB</h1><p class="hero-sub">${tr('heroLine')}</p><div class="hero-actions"><a class="button button-light" href="#jewelry">${tr('exploreJewelry')}</a><a class="button button-outline" href="#watches">${tr('exploreWatches')}</a></div></div><span class="hero-side">MAISON SMB · EST. WITH INTENTION</span><a class="scroll-cue" href="#collections">SCROLL TO DISCOVER <span>↓</span></a></section>`}
function collectionTile(title,sub,file,href,cls=''){return `<a class="collection-tile ${cls}" href="${href}">${img(file,'tile-image',title)}<span class="tile-overline">${sub}</span><h3>${title}</h3><span class="tile-link">DISCOVER ↗</span></a>`}
function home(){return `${hero()}<section class="section collections-section" id="collections"><div class="section-heading"><p class="eyebrow">THE SMB UNIVERSE</p><h2>${tr('featured')}</h2><a href="#collections-page">${tr('viewAll')} ↗</a></div><div class="collection-grid">${collectionTile(tr('jewelry'),'01 / OBJECTS TO TREASURE','Messenger_creation_91F44AA7-9429-4570-8236-F034FEBC33CC.jpeg','#jewelry','tall')}${collectionTile(tr('watches'),'02 / TIME, CONSIDERED','Messenger_creation_7425E1B6-EEBF-4B89-BBF8-38D304CEBA03.jpeg','#watches')}${collectionTile(tr('diamond'),'03 / LIGHT IN FORM','Messenger_creation_C6AEB7FC-8C2C-44F2-A6A3-87C67CEA1783.jpeg','#collections-page')}</div></section><section class="section products-section"><div class="section-heading"><p class="eyebrow">SELECTED PIECES</p><h2>${tr('jewelry')}</h2><a href="#jewelry">${tr('viewAll')} ↗</a></div><div class="product-grid">${products.filter(p=>p.type==='jewelry').slice(0,4).map(card).join('')}</div></section><section class="watch-feature"><div class="watch-feature-img">${img('Messenger_creation_6F929EAF-C636-4572-802A-D06612DA5A75.jpeg','','SMB timepiece')}</div><div class="watch-copy"><p class="eyebrow">TIME, REIMAGINED</p><h2>Every moment,<br><em>made memorable.</em></h2><p>Discover a considered expression of time, shaped by the SMB point of view.</p><a class="text-link" href="#watches">EXPLORE SMB WATCHES ↗</a></div></section><section class="editorial-band"><div class="editorial-copy"><p class="eyebrow">CRAFTSMANSHIP</p><h2>Precision in<br>every detail.</h2><p>Every curve, setting and finish is an invitation to look a little closer.</p><a class="text-link" href="#craftsmanship">DISCOVER OUR CRAFT ↗</a></div>${img('grok_image_1768762213844.jpg','editorial-detail','A close view of SMB craftsmanship')}</section><section class="story-strip"><div class="story-image">${img(campaignImgs[0],'','SMB campaign')}</div><div class="story-text"><p class="eyebrow">A HOUSE OF DISTINCTION</p><h2>Made to be<br><em>remembered.</em></h2><a class="text-link" href="#story">${tr('story')} ↗</a></div></section><section class="final-cta"><p class="eyebrow">A WORLD OF SMB</p><h2>${tr('discover')}</h2><p>Explore the world of exceptional jewelry and watches.</p><a class="button button-light" href="#collections">EXPLORE COLLECTION</a></section>`}
function titleHero(k,over,image){return `<section class="page-hero">${img(image,'page-hero-img',k)}<div class="page-hero-overlay"></div><div><p class="eyebrow">${over}</p><h1>${k}</h1></div></section>`}
function catalog(title, list=products,filters=true){return `${titleHero(title,'SMB / COLLECTIONS',title==='Watches'?'Messenger_creation_7425E1B6-EEBF-4B89-BBF8-38D304CEBA03.jpeg':'Messenger_creation_91F44AA7-9429-4570-8236-F034FEBC33CC.jpeg')}<section class="catalog-wrap"><div class="catalog-intro"><p class="eyebrow">SMB / ${title.toUpperCase()}</p><h2>${title}</h2><p>Considered forms. Distinctive details. Pieces to accompany a lifetime.</p></div>${filters?`<div class="filters"><label>${tr('category')}<select id="categoryFilter"><option value="all">${tr('all')}</option>${[...new Set(list.map(p=>p.category))].map(x=>`<option value="${x}">${x}</option>`).join('')}</select></label><label>${tr('collection')}<select id="collectionFilter"><option value="all">${tr('all')}</option>${[...new Set(list.map(p=>p.collection))].map(x=>`<option value="${x}">${x}</option>`).join('')}</select></label><label>${tr('material')}<select id="materialFilter"><option value="all">${tr('all')}</option>${[...new Set(list.map(p=>p.material))].map(x=>`<option value="${x}">${x}</option>`).join('')}</select></label><label>${tr('sort')}<select id="sortFilter"><option value="featured">${tr('featuredSort')}</option><option value="newest" disabled>${tr('newest')}</option><option value="low" disabled>${tr('low')}</option><option value="high" disabled>${tr('high')}</option></select></label></div>`:''}<div class="product-grid catalog-grid" id="catalogGrid">${list.map(card).join('')}</div></section>`}
function collectionPage(){return `${titleHero(tr('collections'),'THE SMB UNIVERSE','Man_standing_before_logo_2K_20260918222834.jpeg')}<section class="section collection-page-grid">${collectionTile(tr('jewelry'),'01 / THE ART OF ADORNMENT','Messenger_creation_91F44AA7-9429-4570-8236-F034FEBC33CC.jpeg','#jewelry','tall')}${collectionTile(tr('watches'),'02 / TIME, CONSIDERED','Messenger_creation_7425E1B6-EEBF-4B89-BBF8-38D304CEBA03.jpeg','#watches','tall')}${collectionTile(tr('diamond'),'03 / LIGHT IN FORM','Messenger_creation_C6AEB7FC-8C2C-44F2-A6A3-87C67CEA1783.jpeg','#jewelry')}${collectionTile(tr('royal'),'04 / A ROYAL SIGNATURE','Messenger_creation_B651A9C9-E814-4D7B-BF40-E8A8BACCCA6C.jpeg','#jewelry')}</section>`}
function editorial(){return `${titleHero('Editorial','THE SMB JOURNAL','Man_standing_before_logo_2K_20260918222834.jpeg')}<section class="editorial-story"><div class="editorial-story-copy"><p class="eyebrow">A SIGNATURE IN EVERY DETAIL</p><h2>Light, captured<br><em>in its own time.</em></h2><p>SMB brings together a love of considered design and the enduring allure of fine jewelry. Each piece tells its own story through form, reflection and detail.</p></div>${img('grok_image_1770766892161.jpg','','The SMB signature')}</section><div class="campaign-mosaic">${videos.slice(1).map((v,i)=>`<article class="campaign-video"><video muted loop autoplay playsinline preload="none" poster="${A+campaignImgs[i%2]}"><source src="${A+v}" type="video/mp4"></video><span>SMB / CAMPAIGN 0${i+2}</span></article>`).join('')}</div><section class="editorial-quote"><p>“A lasting impression begins with a detail.”</p><span>THE SMB HOUSE</span></section><div class="editorial-last">${img('Messenger_creation_3352C5D6-23C2-4FBB-BD12-975DC28DA98D.jpeg','','A luminous SMB bracelet')}${img('Messenger_creation_5625E5FC-DB19-459A-A2BA-66887AB2499C.png','','An SMB gift, thoughtfully presented')}</div>`}
function storyPage(){return `${titleHero(tr('story'),'THE HOUSE OF SMB','Man_standing_before_logo_2K_20260918222834.jpeg')}<section class="story-intro"><p class="eyebrow">AN EXPRESSION OF DISTINCTION</p><h2>Luxury is found<br>in the <em>feeling.</em></h2><p>SMB is a house of fine jewelry and watches, where a royal sensibility meets modern elegance. Our world is shaped by a devotion to beauty, precision and pieces made to be cherished.</p></section><div class="story-full-image">${img('SMB.png','','The SMB emblem')}</div><section class="story-last"><div><p class="eyebrow">TIMELESS BY NATURE</p><h2>For the moments<br>that become <em>forever.</em></h2><p>From the first sketch to the final finish, our point of view is simple: beauty deserves intention.</p></div>${img('Messenger_creation_5625E5FC-DB19-459A-A2BA-66887AB2499C.png','','An SMB presentation')}</section>`}
function craftPage(){return `${titleHero(tr('craft'),'THE ART OF DETAIL','Messenger_creation_3352C5D6-23C2-4FBB-BD12-975DC28DA98D.jpeg')}<section class="craft-intro"><p class="eyebrow">SMB / THE MAKING</p><h2>${tr('precision')}</h2><p>Precision, detail, craftsmanship and elegance form the foundation of every SMB piece.</p></section><div class="craft-grid">${['grok_image_1768762213844.jpg','Messenger_creation_91F44AA7-9429-4570-8236-F034FEBC33CC.jpeg','grok_image_1772626989606.jpg','Messenger_creation_7425E1B6-EEBF-4B89-BBF8-38D304CEBA03.jpeg','Messenger_creation_D3C256DD-A76A-4654-9B80-69CCBA1E47F9.jpeg','Messenger_creation_C6AEB7FC-8C2C-44F2-A6A3-87C67CEA1783.jpeg','Messenger_creation_3DB69A53-9B32-45E6-BD41-9A028C786F67.jpeg'].map((f,i)=>`<figure>${img(f,'','SMB detail')}<figcaption>0${i+1} / ${['FORM','SETTING','LIGHT','TIME','FINISH','SIGNATURE','CRAFT'][i]}</figcaption></figure>`).join('')}</div><section class="craft-note"><h2>Considered.<br><em>Always.</em></h2><p>Every detail belongs to the whole. The balance of a silhouette, the clarity of a finish, the way a piece catches the light.</p></section>`}
function simplePage(kind){const config={bespoke:{hero:'A PERSONAL SIGNATURE',title:'Bespoke',image:'Messenger_creation_5625E5FC-DB19-459A-A2BA-66887AB2499C.png',copy:'A piece imagined around you. Explore a private design conversation with the SMB house.',cta:tr('consult')},services:{hero:'THE SMB EXPERIENCE',title:'Services',image:'Messenger_creation_5625E5FC-DB19-459A-A2BA-66887AB2499C.png',copy:'Personal attention, thoughtful care and a considered experience at every step.',cta:'DISCOVER OUR SERVICES'},gifts:{hero:'THE ART OF GIVING',title:'Gifts',image:'Messenger_creation_5625E5FC-DB19-459A-A2BA-66887AB2499C.png',copy:'A meaningful gesture, made to be treasured.',cta:'EXPLORE SIGNATURE GIFTS'}}[kind];return `${titleHero(config.title,config.hero,config.image)}<section class="simple-intro"><p class="eyebrow">SMB / ${config.hero}</p><h2>${config.copy}</h2><a class="button button-dark" href="#appointments">${config.cta}</a></section><section class="service-grid">${(kind==='gifts'?products.slice(0,4):[['Private Consultation','A personal conversation with the SMB house.'],['Bespoke','An individual expression, considered together.'],['Jewelry Care','Thoughtful care for pieces to be cherished.'],['Watch Care','A considered approach to your timepiece.']]).map((v,i)=>kind==='gifts'?card(v):`<article><span>0${i+1}</span><h3>${v[0]}</h3><p>${v[1]}</p><a href="#appointments">ENQUIRE ↗</a></article>`).join('')}</section>`}
function appointments(){return `${titleHero('Appointments','A PRIVATE SMB EXPERIENCE','Messenger_creation_91F44AA7-9429-4570-8236-F034FEBC33CC.jpeg')}<section class="appointment-layout"><div><p class="eyebrow">PERSONAL SERVICE</p><h2>Time, reserved<br>for <em>you.</em></h2><p>Share a few details and our team will be in touch to arrange your private appointment.</p></div><form id="appointmentForm" class="form-grid"><label>Name<input required name="name" autocomplete="name"></label><label>Email<input required name="email" type="email" autocomplete="email"></label><label>Phone<input name="phone" type="tel" autocomplete="tel"></label><label>Preferred date<input name="date" type="date"></label><label>Preferred time<select name="time"><option>Morning</option><option>Afternoon</option><option>Evening</option></select></label><label>Service<select name="service"><option>Private Consultation</option><option>Bespoke</option><option>Jewelry Care</option><option>Watch Care</option><option>Gift Services</option></select></label><label class="span-two">Message<textarea name="message" rows="3"></textarea></label><button class="button button-dark span-two">${tr('appointment')}</button><small class="span-two form-note">Your request is prepared on this device. An appointment is not confirmed until SMB contacts you.</small></form></section>`}
function productPage(id){const p=products.find(x=>x.id===id);if(!p)return `<section class="empty-page"><p>Piece not found.</p><a href="#jewelry">Return to collection ↗</a></section>`;return `<section class="product-detail"><div class="gallery-main">${p.images.map((f,i)=>`<button class="gallery-image" data-gallery="${i}">${img(f,'',p.name)}<span>＋</span></button>`).join('')}</div><div class="product-info"><p class="eyebrow">${p.collection.toUpperCase()}</p><h1>${p.name}</h1><p class="detail-price">${tr('request')}</p><p>${tr('description')}</p><div class="detail-rule"></div><p><small>${tr('material')}</small><br>${p.material}</p><p><small>${tr('availability')}</small><br>${tr('available')}</p><div class="detail-actions"><button class="button button-dark" data-add="${p.id}">${tr('add')}</button><button class="wish-detail ${wish.includes(p.id)?'active':''}" data-wish="${p.id}">♡ <span>WISHLIST</span></button></div><p class="detail-foot">${tr('details')} <span>+</span></p></div></section><section class="section related"><div class="section-heading"><p class="eyebrow">CONTINUE DISCOVERING</p><h2>Considered pieces</h2></div><div class="product-grid">${products.filter(x=>x.id!==p.id).slice(0,4).map(card).join('')}</div></section>`}
function bagPage(){if(!bag.length)return `<section class="empty-page"><p class="eyebrow">${tr('bag')}</p><h1>${tr('empty')}</h1><a class="button button-dark" href="#jewelry">EXPLORE JEWELRY</a></section>`;return `<section class="bag-page"><div><p class="eyebrow">SMB / ${tr('bag')}</p><h1>${tr('bag')}</h1>${bag.map(x=>{let p=products.find(p=>p.id===x.id);return `<article class="bag-item">${img(p.images[0],'',p.name)}<div><a href="#product/${p.id}">${p.name}</a><p>${p.collection}</p><div class="qty-control"><button data-qty="${p.id}" data-delta="-1">−</button><span>${x.qty}</span><button data-qty="${p.id}" data-delta="1">+</button></div></div><button class="remove-btn" data-remove="${p.id}">${tr('remove')} ×</button></article>`}).join('')}</div><aside class="bag-summary"><p>${tr('subtotal')}</p><h2>${tr('request')}</h2><p>Final pricing will be shared by our team.</p><a class="button button-dark" href="#checkout">${tr('checkout')}</a></aside></section>`}
function checkout(){return `<section class="checkout-page"><div><p class="eyebrow">SMB / PRIVATE ORDER</p><h1>Complete your request</h1><p>Our team will contact you to confirm availability and pricing. No payment is taken on this page.</p><form id="checkoutForm" class="form-grid"><label>Full Name<input required name="name"></label><label>Email<input required type="email" name="email"></label><label>Phone<input name="phone" type="tel"></label><label>Country<input name="country"></label><label>City<input name="city"></label><label>Address<input name="address"></label><button class="button button-dark span-two">REQUEST ORDER</button><small class="span-two form-note">Submitting sends no payment. This demo stores your request only in this browser.</small></form></div><aside><h3>ORDER SUMMARY</h3>${bag.map(x=>{const p=products.find(y=>y.id===x.id);return `<p>${p.name} <span>× ${x.qty}</span></p>`}).join('')}<hr><strong>${tr('request')}</strong></aside></section>`}
function pieceCount(n,locale=lang){if(locale==='fr')return `${n} pièce${n===1?'':'s'} sélectionnée${n===1?'':'s'}.`;if(locale==='ar')return `${n} ${n===1?'قطعة مختارة':'قطع مختارة'}`;return `${n} considered piece${n===1?'':'s'}.`}
function wishlistPage(){const items=products.filter(p=>wish.includes(p.id));return `<section class="catalog-wrap wish-page"><div class="catalog-intro"><p class="eyebrow">SMB / SAVED PIECES</p><h1>Wishlist</h1><p>${items.length?`<span data-piece-count="${items.length}">${pieceCount(items.length)}</span>`:tr('wishEmpty')}</p></div>${items.length?`<div class="product-grid">${items.map(card).join('')}</div>`:''}</section>`}
function render(preserveScroll=false){const oldScroll=scrollY;headerText();const hash=decodeURIComponent(location.hash.slice(1)||'home');let page;if(hash.startsWith('product/'))page=productPage(hash.split('/')[1]);else if(hash==='home')page=home();else if(hash==='collections'||hash==='collections-page')page=collectionPage();else if(hash==='jewelry')page=catalog('Jewelry',products.filter(p=>p.type==='jewelry'));else if(hash==='watches')page=catalog('Watches',products.filter(p=>p.type==='watch'));else if(hash==='editorial'||hash==='campaigns')page=editorial();else if(hash==='story')page=storyPage();else if(hash==='craftsmanship')page=craftPage();else if(hash==='appointments')page=appointments();else if(hash==='bespoke'||hash==='services'||hash==='gifts')page=simplePage(hash);else if(hash==='bag')page=bagPage();else if(hash==='checkout')page=checkout();else if(hash==='wishlist')page=wishlistPage();else page=home();app.innerHTML=page;localize(document.body);document.querySelector('#header').classList.toggle('scrolled',scrollY>24);window.scrollTo(0,preserveScroll?oldScroll:0);updateCounts();bindPage();}
function save(){safeSet('smb-wishlist',JSON.stringify(wish));safeSet('smb-bag',JSON.stringify(bag));updateCounts()}
function updateCounts(){document.querySelector('#wishCount').textContent=wish.length;document.querySelector('#bagCount').textContent=bag.reduce((n,x)=>n+x.qty,0)}
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;localize(el);el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2400)}
function addBag(id){const found=bag.find(x=>x.id===id);found?found.qty++:bag.push({id,qty:1});save();toast('Added to your SMB bag');}
function toggleWish(id){wish.includes(id)?wish=wish.filter(x=>x!==id):wish.push(id);save();render()}
function showQuick(p){modal.querySelector('.modal-content').innerHTML=`<div class="quick-view">${img(p.images[0],'',p.name)}<div><p class="eyebrow">${p.collection.toUpperCase()}</p><h2>${p.name}</h2><p>${tr('request')}</p><p>${tr('description')}</p><div class="quick-actions"><button class="button button-dark" data-add="${p.id}">${tr('add')}</button><a class="text-link" href="#product/${p.id}">VIEW PIECE ↗</a></div></div></div>`;localize(modal);modal.classList.add('open');modal.setAttribute('aria-hidden','false');bindGlobal()}
function bindPage(){document.querySelectorAll('[data-wish]').forEach(b=>b.onclick=e=>{e.preventDefault();toggleWish(b.dataset.wish)});document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>showQuick(products.find(p=>p.id===b.dataset.quick)));document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>addBag(b.dataset.add));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{bag=bag.filter(x=>x.id!==b.dataset.remove);save();render()});document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{let item=bag.find(x=>x.id===b.dataset.qty);item.qty+=Number(b.dataset.delta);if(item.qty<1)bag=bag.filter(x=>x!==item);save();render()});document.querySelectorAll('[data-gallery]').forEach(b=>b.onclick=()=>{const p=products.find(x=>location.hash.includes(x.id));if(p)openGallery(p,Number(b.dataset.gallery))});const filters=['categoryFilter','collectionFilter','materialFilter','sortFilter'].map(id=>document.getElementById(id));if(filters.some(Boolean))filters.filter(Boolean).forEach(el=>el.onchange=applyFilters);const ap=document.querySelector('#appointmentForm');if(ap)ap.onsubmit=e=>{e.preventDefault();toast('This demo does not send appointment requests. Please contact SMB to arrange a visit.');ap.reset()};const co=document.querySelector('#checkoutForm');if(co)co.onsubmit=e=>{e.preventDefault();safeSet('smb-order-request',JSON.stringify({items:bag,customer:Object.fromEntries(new FormData(co))}));toast('Order request saved on this device. No payment was taken.');bag=[];save();setTimeout(()=>location.hash='#home',1600)}}
function applyFilters(){const cat=document.querySelector('#categoryFilter')?.value||'all',col=document.querySelector('#collectionFilter')?.value||'all',mat=document.querySelector('#materialFilter')?.value||'all';let filtered=products.filter(p=>(location.hash==='#watches'?p.type==='watch':p.type==='jewelry')&&(cat==='all'||p.category===cat)&&(col==='all'||p.collection===col)&&(mat==='all'||p.material===mat));document.querySelector('#catalogGrid').innerHTML=filtered.length?filtered.map(card).join(''):`<p>${tr('noResults')}</p>`;localize(document.querySelector('#catalogGrid'));bindPage()}
function openGallery(p,index){let at=index;function show(){modal.querySelector('.modal-content').innerHTML=`<div class="lightbox"><button class="light-prev" aria-label="Previous image">←</button>${img(p.images[at],'',p.name)}<button class="light-next" aria-label="Next image">→</button><div>${at+1} / ${p.images.length}</div></div>`;localize(modal);modal.querySelector('.light-prev').onclick=()=>{at=(at+p.images.length-1)%p.images.length;show()};modal.querySelector('.light-next').onclick=()=>{at=(at+1)%p.images.length;show()}}show();modal.classList.add('open');modal.setAttribute('aria-hidden','false')}
function bindGlobal(){modal.querySelector('.modal-close').onclick=closeModal;modal.querySelector('.modal-backdrop').onclick=closeModal;modal.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>addBag(b.dataset.add))}
function closeModal(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true')}
function openSearch(){document.querySelector('#searchPanel').classList.add('open');document.querySelector('#searchInput').focus()}
function changeLanguage(next){lang=validLanguages.includes(next)?next:'en';safeSet('smb-language',lang);headerText();localize(document.body);document.querySelectorAll('[data-piece-count]').forEach(el=>{el.textContent=pieceCount(Number(el.dataset.pieceCount),lang)})}
function setDrawer(open){const drawer=document.querySelector('#mobileDrawer'),toggle=document.querySelector('#menuToggle');drawer.classList.toggle('open',open);drawer.setAttribute('aria-hidden',String(!open));drawer.inert=!open;toggle.setAttribute('aria-expanded',String(open))}
document.addEventListener('click',e=>{if(e.target.closest('.search-open'))openSearch();if(e.target.closest('.search-close'))document.querySelector('#searchPanel').classList.remove('open');if(e.target.closest('.modal-close')||e.target.classList.contains('modal-backdrop'))closeModal();if(e.target.closest('#menuToggle'))setDrawer(true);if(e.target.closest('.drawer-close'))setDrawer(false);if(e.target.closest('#mobileDrawer a'))setDrawer(false);const l=e.target.closest('[data-lang]');if(l){changeLanguage(l.dataset.lang)}});
document.querySelector('#language').onchange=e=>changeLanguage(e.target.value);
document.querySelector('#searchInput').oninput=e=>{let q=e.target.value.toLocaleLowerCase(lang).trim(),results=products.filter(p=>[p.name,p.collection,p.category,t[lang][p.name],t[lang][p.collection],t[lang][p.category]].filter(Boolean).join(' ').toLocaleLowerCase(lang).includes(q));document.querySelector('#searchResults').innerHTML=q?results.map(p=>`<a class="search-result" href="#product/${p.id}">${img(p.images[0],'',p.name)}<span>${p.name}<small>${p.collection}</small></span><b>${tr('request')}</b></a>`).join('')||`<p>${tr('noResults')}</p>`:'';localize(document.querySelector('#searchResults'))};
window.addEventListener('hashchange',()=>{render();document.querySelector('#searchPanel').classList.remove('open')});window.addEventListener('scroll',()=>document.querySelector('#header').classList.toggle('scrolled',scrollY>24),{passive:true});document.querySelector('#newsletterForm').onsubmit=e=>{e.preventDefault();document.querySelector('#newsletterNote').textContent='Thank you for your interest in SMB.';localize(document.querySelector('#newsletterNote'));e.target.reset()};document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.querySelector('#searchPanel').classList.remove('open');setDrawer(false)}});render();
